import assert from 'node:assert/strict';import {mkdtempSync,mkdirSync,writeFileSync,readFileSync,rmSync,existsSync} from 'node:fs';import {tmpdir} from 'node:os';import {join,resolve} from 'node:path';import {createHash} from 'node:crypto';import {APP_SHA,BASE_MANIFEST,prepare,verifyBase,patchApp} from './prepare-product-tabs-delta.mjs';
const [rootArg,manifestArg]=process.argv.slice(2);assert.ok(rootArg&&manifestArg);const root=resolve(rootArg),manifest=readFileSync(manifestArg);const sha=b=>createHash('sha256').update(b).digest('hex');const temp=mkdtempSync(join(tmpdir(),'hkia-product-tabs-'));const bundleDir=join(temp,'build');mkdirSync(bundleDir);const bundle=join(bundleDir,'product-tabs.mjs');
// Sentinel is test data only; it is never a compiled/distribution candidate.
writeFileSync(bundle,'export function mountProductTabs(){throw Error("TEST_ONLY");}\n');
try{
 const out=join(temp,'delta'),result=prepare(root,manifest,bundle,out);assert.equal(result.baseManifestSha256,BASE_MANIFEST);assert.equal(result.unchanged,4145);assert.deepEqual(Object.keys(result.changes),['src/app.js','src/product-tabs.mjs']);assert.equal(result.changes['src/app.js'].before,APP_SHA);assert.equal(sha(readFileSync(join(root,'src/app.js'))),APP_SHA);assert.deepEqual(readFileSync(join(out,'src/app.js')),patchApp(readFileSync(join(root,'src/app.js'))));assert.deepEqual(readFileSync(join(out,'src/product-tabs.mjs')),readFileSync(bundle));assert.deepEqual(JSON.parse(readFileSync(join(out,'delta-manifest.json'))),result);
 assert.throws(()=>prepare(root,manifest,bundle,out),/fresh delta/);assert.throws(()=>verifyBase(root,Buffer.concat([manifest,Buffer.from(' ')])),/wrong fixed V30 manifest/);assert.throws(()=>patchApp(Buffer.from('bootstrap();')),/wrong V30 app/);
 const nested=join(root,'unapproved-delta');assert.throws(()=>prepare(root,manifest,bundle,nested),/outside input trees/);assert.equal(existsSync(nested),false);assert.throws(()=>prepare(root,manifest,bundle,join(bundleDir,'nested')),/outside input trees/);
 writeFileSync(join(bundleDir,'unexpected.js'),'export {};');assert.throws(()=>prepare(root,manifest,bundle,join(temp,'bad-extra')),/unexpected bundle files/);rmSync(join(bundleDir,'unexpected.js'));
 writeFileSync(bundle,'export {};\n//# sourceMappingURL=secret.map\n');assert.throws(()=>prepare(root,manifest,bundle,join(temp,'bad-map')),/source map forbidden/);
 verifyBase(root,manifest);console.log(JSON.stringify({baseReverified:4146,webpUnchanged:4076,positiveDelta:'1 MOD 1 ADD (sentinel only)',negativeCases:7,originalUnchanged:true}));
}finally{rmSync(temp,{recursive:true,force:true});}
